  "nodes": {
    "Component": [
      {
        "component_id": "comp_power_supply",
        "name": "Power Supply",
        "description": "The power supply that houses internal components and connects to the torch lead gas supply fitting.",
        "category": "power"
      },
      {
        "component_id": "comp_fan",
        "name": "Fan",
        "description": "The fan, which may affect the appearance of a leak during leak testing and can be disconnected from J5 on the power board.",
        "category": "cooling"
      },
      {
        "component_id": "comp_air_compressor",
        "name": "Air Compressor",
        "description": "The internal air compressor; its voltage and operation are checked when air pressure is low.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_compressor_driver_board",
        "name": "Compressor-driver board",
        "description": "The board associated with the compressor; its diagnostic LED D5 is referenced for checking compressor voltage.",
        "category": "control"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "The board with connector J5, from which the fan may be disconnected during leak testing.",
        "category": "electrical"
      },
      {
        "component_id": "comp_diagnostic_led_d5",
        "name": "Diagnostic LED (D5)",
        "description": "The diagnostic LED on the compressor-driver board referenced in the compressor voltage check.",
        "category": "diagnostic"
      },
      {
        "component_id": "comp_solenoid_valve",
        "name": "Solenoid valve",
        "description": "A valve with gas hoses connected to each side, included among the gas supply line leak-check points.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_air_filter_assembly",
        "name": "Air filter assembly",
        "description": "The assembly where the filter bowl screws in, included among the gas supply line leak-check points.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_filter_bowl",
        "name": "Filter bowl",
        "description": "The bowl that screws into the air filter assembly and connects to the drain hose.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_drain_hose",
        "name": "Drain hose",
        "description": "The hose connected to the bottom of the filter bowl and routed to the base of the power supply.",
        "category": "pneumatic"
      }
    ],
